const multiple = true;
const $ = QF.dom.$, on = QF.dom.on;
const reply = await QF.practice.getQuestion(); if (!reply.ok) throw new Error(reply.error.message);
const question = reply.data;
QF.layout.configure({ cardWidth: 720, maxCardWidth: '100%', horizontalAlign: 'center', verticalAlign: 'center', padding: 20 });
QF.ui.configure({ typeLabel: false, position: false, score: false, state: false, submit: false, retry: false, confirmation: false, note: false, sources: false, draftToggle: true, draftToolbar: true, draftZoom: true });
let confirming = false, actionBusy = false, refreshRevision = 0, answerRevision = 0, answerWrites = 0;
$('[data-type-label]').textContent = multiple ? '多选题' : '单选题';
$('[data-choice-hint]').textContent = multiple ? '请选择所有符合题意的选项' : '请选择一个符合题意的选项';
async function runAction(action) {
  if (actionBusy) return; actionBusy = true;
  try { await refresh(); const response = await action(); if (!response.ok) QF.ui.notify(response.error.message); return response; }
  finally { actionBusy = false; await refresh(); }
}
on($('[data-submit-answer]'), 'click', () => { confirming = true; $('[data-answer-confirm]').hidden = false; refresh().then(() => $('[data-confirm-answer]').focus()); });
on($('[data-cancel-answer]'), 'click', () => { confirming = false; refresh(); });
on($('[data-confirm-answer]'), 'click', () => { confirming = false; return runAction(() => QF.practice.submit()); });
on($('[data-retry-answer]'), 'click', () => runAction(() => QF.practice.retry()));
on($('[data-sources]'), 'click', event => { const button = event.target.closest('[data-source-index]'); if (button && !button.disabled) return runAction(() => QF.sources.open(Number(button.dataset.sourceIndex))); });
$('[data-prompt]').textContent = question.prompt.text;
const controls = [];
question.payload.options.forEach((option, index) => {
  const row = document.createElement('label'); row.className = 'qf-choice-option'; row.dataset.optionId = option.id;
  const input = document.createElement('input'); input.type = multiple ? 'checkbox' : 'radio'; input.name = 'qf-choice-' + question.id; input.value = option.id;
  const letter = document.createElement('span'); letter.className = 'qf-option-letter'; letter.textContent = String.fromCharCode(65 + index) + '.'; letter.setAttribute('aria-hidden', 'true');
  const text = document.createElement('span'); text.className = 'qf-option-text'; text.textContent = option.content.text;
  input.setAttribute('aria-label', String.fromCharCode(65 + index) + '. ' + option.content.text);
  const feedback = document.createElement('span'); feedback.className = 'qf-option-feedback'; feedback.hidden = true;
  row.append(input, letter, text, feedback); $('[data-options]').append(row); controls.push({ option, input, row, feedback });
  on(input, 'change', async () => {
    // Invalidate reads already in flight; never repaint an older answer over a newer click.
    ++answerRevision; ++refreshRevision; ++answerWrites;
    const selectedOptionIds = controls.filter(c => c.input.checked).map(c => c.option.id);
    row.classList.toggle('selected', input.checked);
    try {
      const response = await QF.answer.update({ selectedOptionIds });
      if (!response.ok) QF.ui.notify(response.error.message);
    } finally {
      --answerWrites;
      if (!answerWrites) await refresh();
    }
  });
});
async function refresh() {
  const revision = ++refreshRevision, answerVersion = answerRevision;
  const [a, c, r, s, n] = await Promise.all([QF.answer.get(), QF.host.getContext(), QF.practice.getResult(), QF.practice.getState(), QF.navigation.getState()]);
  if (revision !== refreshRevision || answerVersion !== answerRevision) return;
  if (!a.ok || !c.ok || !r.ok || !s.ok) return;
  const selected = new Set(a.data.selectedOptionIds || []), result = r.data;
  const capabilities = c.data.capabilities, state = s.data;
  const readOnly = c.data.mode === 'HISTORY' || c.data.mode === 'PREVIEW';
  const permissions = c.data.permissions.granted;
  $('[data-question-position]').textContent = Number.isInteger(state.index) ? `第 ${state.index + 1} / ${state.total} 题` : '';
  $('[data-max-score]').textContent = `分值：${state.maxScore ?? '未设置'}`;
  $('[data-answer-state]').textContent = ({ UNANSWERED: '未作答', DRAFT: '已选择', SUBMITTED: '已提交', RETRYING: '重试中', REVISING: '修订中' })[state.state] || '';
  if (!capabilities.submit || result || c.data.mode === 'HISTORY' || c.data.mode === 'PREVIEW') confirming = false;
  $('[data-answer-confirm]').hidden = !confirming;
  // Temporary interaction locks disable actions without changing the card's layout.
  $('[data-submit-answer]').hidden = readOnly || !permissions.includes('practice.submit') || Boolean(result);
  $('[data-submit-answer]').disabled = actionBusy || confirming || !capabilities.submit || selected.size === 0;
  $('[data-retry-answer]').hidden = readOnly || !permissions.includes('practice.retry') || !result;
  $('[data-retry-answer]').disabled = actionBusy || !capabilities.retry;
  $('[data-confirm-answer]').disabled = actionBusy || !capabilities.submit || selected.size === 0;
  const sourceRows = $('[data-sources]'); sourceRows.replaceChildren();
  const sources = n.ok ? n.data.sources : []; $('[data-source-section]').hidden = !sources.length;
  sources.forEach((source, index) => {
    const row = document.createElement('div'); row.className = 'qf-type-source'; const button = document.createElement('button'); button.type = 'button'; button.textContent = source.label; button.disabled = actionBusy || !capabilities.viewSources || !source.navigable; button.dataset.sourceIndex = index;
    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message; row.append(button, message); sourceRows.append(row);
  });
  $('[data-stage-note]').textContent = c.data.mode === 'HISTORY' ? '历史草稿 · 只读' : c.data.mode === 'PREVIEW' ? '只读预览' : '草稿自动保存；提交后冻结，重试从空白草稿开始。';
  const correct = result?.reference?.answerSpec?.correctOptionIds || result?.correctOptionIds || [];
  for (const { option, input, row, feedback } of controls) {
    if (!answerWrites) input.checked = selected.has(option.id);
    input.disabled = actionBusy || confirming || !capabilities.editAnswer;
    row.classList.toggle('selected', input.checked);
    row.classList.toggle('correct', Boolean(result) && correct.includes(option.id));
    row.classList.toggle('incorrect', Boolean(result) && input.checked && !correct.includes(option.id));
    feedback.hidden = !result || (!input.checked && !correct.includes(option.id));
    feedback.textContent = correct.includes(option.id) ? (input.checked ? '正确 · 已选' : '正确答案') : '你的答案';
  }
  $('[data-result]').hidden = !result;
  if (result) {
    $('[data-verdict]').textContent = result.status === 'CORRECT' ? '回答正确' : result.status === 'INCORRECT' ? '回答错误' : '未评分';
    $('[data-verdict]').className = result.status === 'CORRECT' ? 'correct' : 'incorrect';
    $('[data-score]').textContent = '得分：' + (result.score ?? '未评分') + ' / ' + result.maxScore;
    $('[data-correct-answer]').textContent = '正确答案：' + question.payload.options.map((o, i) => correct.includes(o.id) ? String.fromCharCode(65 + i) : null).filter(Boolean).join('、');
    QF.content.render($('[data-analysis]'), result.reference?.analysis || result.analysis || { kind: 'TEXT', text: '' });
  }
}
QF.host.subscribe(refresh); await refresh();

assets.rulesSource:
QF.defineQuestionType({
  type: "MULTIPLE_CHOICE",
  validate(q) {
    const errors=[];
    if(q.prompt?.kind!=='TEXT'||!(q.prompt.text||'').trim()) errors.push('请填写普通文本题干');
    const options=q.payload?.options||[],ids=new Set(options.map(o=>o.id));
    if(options.length<2||ids.size!==options.length) errors.push('至少需要两个具有独立标识的选项');
    if(options.some(o=>o.content?.kind!=='TEXT'||!(o.content.text||'').trim())) errors.push('请填写普通文本选项');
    const correct=q.answerSpec?.correctOptionIds||[];
    if(!correct.length||new Set(correct).size!==correct.length||correct.some(id=>!ids.has(id))) errors.push('请选择有效的正确答案');
    if(!Number.isFinite(q.scoreSpec?.defaultMaxScore)||q.scoreSpec.defaultMaxScore<=0) errors.push('分值必须为正数');
    return errors;
  },
  validateAnswer(q,a) {
    const ids=a.selectedOptionIds||[],available=new Set(q.payload.options.map(o=>o.id));
    if(!Array.isArray(ids)) return {empty:false,errors:['所选答案无效']};
    return {empty:ids.length===0,errors:!Array.isArray(ids)||new Set(ids).size!==ids.length||ids.some(id=>!available.has(id))?['所选答案无效']:[]};
  },
  grade(ctx) {
    const selected=new Set(ctx.answer.selectedOptionIds||[]),correct=ctx.question.answerSpec.correctOptionIds;
    const same=selected.size===correct.length&&correct.every(id=>selected.has(id));
    return ctx.reportResult({score:same?ctx.maxScore:0});
  }
});

assets.stylesSource:
.qf-choice-editor,.qf-choice-practice {
  --choice-accent:#7962ad;--choice-soft:#f5f1fb;--choice-line:#e8e3ed;--choice-muted:#8a8295;
  font:15px/1.65 Arial,"Microsoft YaHei",sans-serif;color:#302c3b;min-width:0;
}
.qf-choice-editor *, .qf-choice-practice *{box-sizing:border-box}
.qf-extension-page [hidden]{display:none!important}
.qf-choice-editor .muted,.qf-choice-practice .muted{font-size:12px;color:var(--choice-muted);margin:0}
.qf-type-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}
.qf-heading-copy{display:grid;gap:3px;flex:1}
.qf-eyebrow{font-size:11px;color:var(--choice-muted);letter-spacing:1px}
.qf-editor-heading strong{font-size:22px;font-weight:600;line-height:1.45}
.qf-type-tag{padding:4px 11px;border-radius:6px;color:var(--choice-accent);background:#eee9f7;font-size:12px}
.qf-type-meta{display:flex;justify-content:space-between;gap:12px;font-size:12px;color:var(--choice-muted);margin:12px 0 24px}
.qf-type-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:24px 0 0}
.qf-editor-actions{margin:18px 0 6px;padding-bottom:20px;border-bottom:1px solid var(--choice-line)}
.qf-choice-editor button,.qf-choice-practice button,.qf-choice-editor select {
  font:13px/1.5 Arial,"Microsoft YaHei",sans-serif;min-height:36px;padding:7px 13px;
  border:1px solid #ded7e9;border-radius:8px;background:white;color:var(--choice-accent);cursor:pointer;
  transition:background .15s,border-color .15s;
}
.qf-choice-editor button:hover,.qf-choice-practice button:hover{background:var(--choice-soft);border-color:#c9bcde}
.qf-choice-editor button.primary,.qf-choice-practice button.primary{background:var(--choice-accent);color:white;border-color:var(--choice-accent);padding-left:20px;padding-right:20px}
.qf-choice-editor button.primary:hover,.qf-choice-practice button.primary:hover{background:#6a539d}
.qf-choice-editor button:disabled,.qf-choice-practice button:disabled{opacity:.45;cursor:default}
.qf-choice-editor button.danger,.qf-choice-editor button.quiet-danger{color:#bd5264}
.qf-choice-editor button:focus-visible,.qf-choice-practice button:focus-visible,.qf-choice-editor select:focus-visible{outline:2px solid #ad97d5;outline-offset:3px}
.qf-editor-section{margin-top:24px}
.qf-field{display:grid;gap:10px}
.qf-field-title,.qf-section-heading strong,.qf-type-sources>strong{font-size:14px;font-weight:600}
.qf-section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}
.qf-choice-editor textarea,.qf-choice-editor input[type=number],.qf-source-input input {
  width:100%;font:inherit;line-height:1.65;padding:11px 13px;border:1px solid #dfd9e8;border-radius:8px;
  background:#fff;color:inherit;outline:none;
}
.qf-choice-editor textarea{resize:vertical;display:block}
.qf-choice-editor textarea:focus,.qf-choice-editor input[type=number]:focus,.qf-source-input input:focus{border-color:#a18ac6;box-shadow:0 0 0 3px #7962ad0d}
.qf-edit-options{display:grid;gap:10px;margin-top:14px}
.qf-choice-edit-row{display:grid;grid-template-columns:20px 28px minmax(0,1fr) auto;align-items:center;gap:10px;padding:9px 10px;border:1px solid var(--choice-line);border-radius:10px;background:#fcfbfd}
.qf-choice-edit-row.is-correct{background:var(--choice-soft);border-color:#d8cbe9}
.qf-option-letter{font-weight:600;color:#756b86;font-size:14px;flex:none}
.qf-choice-edit-row.is-correct .qf-option-letter{color:var(--choice-accent)}
.qf-choice-edit-row textarea{padding:8px 10px;min-height:42px;font-size:14px}
.qf-choice-edit-row button{padding:6px 8px;min-height:32px;border-color:transparent;background:transparent;color:var(--choice-muted);font-size:12px}
.qf-choice-edit-row button:hover{color:#bd5264;background:#fff1f3;border-color:transparent}
.qf-score-input{display:flex;align-items:center;gap:10px;color:var(--choice-muted);font-size:13px}
.qf-score-input input[type=number]{width:112px;color:#302c3b}
.qf-analysis-editor{margin-top:12px}
.qf-choice-prompt{margin:0 0 14px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:18px;font-weight:500;line-height:1.8}
.qf-choice-hint{margin-bottom:14px!important}
.qf-choice-options{display:grid;gap:10px}
.qf-choice-option{display:flex;align-items:flex-start;gap:12px;padding:14px 15px;border:1px solid #eeeaf2;border-radius:10px;background:#fcfbfd;cursor:pointer;transition:background .15s,border-color .15s}
.qf-choice-option:hover{background:#f8f5fc;border-color:#d8cde7}
.qf-choice-option.selected{background:var(--choice-soft);border-color:#d4c5e7}
.qf-choice-option .qf-option-text{flex:1;min-width:0;white-space:pre-wrap;overflow-wrap:anywhere}
.qf-choice-option input,.qf-choice-edit-row>input {
  appearance:none;-webkit-appearance:none;width:20px;height:20px;flex:none;position:relative;
  border:1.5px solid #cec7d6;border-radius:50%;margin:2px 0 0;background:white;cursor:pointer;
}
.qf-choice-option input[type=checkbox],.qf-choice-edit-row>input[type=checkbox]{border-radius:5px}
.qf-choice-option input:checked,.qf-choice-edit-row>input:checked{border-color:var(--choice-accent)}
.qf-choice-option input:checked:after,.qf-choice-edit-row>input:checked:after{content:"";position:absolute;inset:4px;background:var(--choice-accent);border-radius:50%}
.qf-choice-option input[type=checkbox]:checked:after,.qf-choice-edit-row>input[type=checkbox]:checked:after{content:"✓";inset:-4px 0 0;color:var(--choice-accent);background:transparent;font-size:19px;text-align:center}
.qf-choice-option input:focus-visible,.qf-choice-edit-row>input:focus-visible{outline:2px solid #ad97d5;outline-offset:3px}
.qf-choice-option input:disabled{opacity:1;cursor:default}
.qf-choice-option.correct{background:#edf7f3;border-color:#cce8dd;color:#13876d}
.qf-choice-option.incorrect{background:#fff0f2;border-color:#f2d3db;color:#c64b63}
.qf-choice-option.correct .qf-option-letter{color:#13876d}
.qf-choice-option.incorrect .qf-option-letter{color:#c64b63}
.qf-option-feedback{font-size:11px;line-height:24px;flex:none;white-space:nowrap}
.qf-inline-confirm{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:14px 16px;margin-top:16px;background:var(--choice-soft);border:1px solid #e0d6ed;border-radius:10px;font-size:13px}
.qf-inline-confirm>span{flex:1;min-width:180px}
.qf-result-panel{margin-top:26px;padding:20px;border:1px solid var(--choice-line);border-radius:12px;background:#fcfbfd}
.qf-result-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.qf-result-heading p{margin:0}
.qf-result-heading [data-verdict]{font-size:15px;font-weight:600}
.qf-result-heading .correct{color:#13876d}
.qf-result-heading .incorrect{color:#c64b63}
.qf-result-score{font-size:13px;color:var(--choice-accent);padding:4px 10px;background:#eee9f7;border-radius:6px}
.qf-correct-answer{margin:12px 0 0;font-size:13px;color:#6a6178}
.qf-result-analysis{border-top:1px solid var(--choice-line);padding-top:16px;margin-top:16px}
.qf-result-analysis>strong{font-size:13px;font-weight:600}
.qf-result-analysis [data-analysis]{margin-top:8px;overflow-wrap:anywhere}
.qf-type-sources{border-top:1px solid var(--choice-line);padding-top:18px;margin-top:26px;font-size:13px}
.qf-type-source{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:10px}
.qf-type-source>button:first-child{max-width:100%;overflow-wrap:anywhere;text-align:left}
.qf-type-source>.muted{flex:1}
.qf-source-input{display:flex;align-items:center;gap:10px;margin-top:12px}
.qf-source-input input{flex:1;min-width:0;font-size:13px}
.qf-source-input button{flex:none}
.qf-choice-practice [data-stage-note]{margin-top:24px;font-size:11px;line-height:1.7}
@media(max-width:520px){
  .qf-editor-heading{flex-wrap:wrap}.qf-heading-copy{min-width:130px}.qf-editor-heading strong{font-size:20px}
  .qf-choice-edit-row{grid-template-columns:20px 22px minmax(0,1fr) auto;gap:6px;padding:8px}
  .qf-choice-edit-row button{padding:6px 3px}.qf-choice-option{padding:12px 10px;gap:8px}
  .qf-option-feedback{font-size:10px}.qf-result-panel{padding:16px}.qf-choice-prompt{font-size:17px}
}
